import React, { useState, useMemo, useEffect } from 'react';
import { Search } from 'lucide-react';
import axios from 'axios';

const UsersList = ({ onSelectUser }) => {
  const [users, setUsers] = useState([]);
  const [search, setSearch] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const token = localStorage.getItem('token');

  const fetchUsers = async () => {
    try {
      setLoading(true);
      const response = await axios.get('http://localhost:5000/users/admins', {
        headers: {
          Authorization: token ? `Bearer ${token}` : ''
        }
      });
      setUsers(response.data.users);
      setError(null);
    } catch (err) {
      console.error('Erreur fetchUsers:', err);
      setError('Impossible de récupérer les utilisateurs');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchUsers();
  }, []);

  const filteredUsers = useMemo(() => {
    if (!search.trim()) return users;
    return users.filter(user =>
      `${user.first_name} ${user.last_name}`.toLowerCase().includes(search.toLowerCase()) ||
      user.email.toLowerCase().includes(search.toLowerCase()) ||
      user.role.toLowerCase().includes(search.toLowerCase())
    );
  }, [users, search]);

  return (
    <div className="p-4 bg-white dark:bg-neutral-900 rounded-2xl shadow-lg">
      <div className="relative mb-4">
        <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-neutral-400" size={18} />
        <input
          type="text"
          placeholder="Rechercher un utilisateur..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          className="w-full pl-10 pr-4 py-2 border rounded-lg text-sm dark:bg-neutral-800 dark:text-white"
        />
      </div>

      {loading ? (
        <p className="text-center text-neutral-500">Chargement des utilisateurs...</p>
      ) : error ? (
        <p className="text-center text-red-500">{error}</p>
      ) : filteredUsers.length === 0 ? (
        <p className="text-center text-neutral-500">Aucun utilisateur trouvé</p>
      ) : (
        <ul className="divide-y divide-neutral-200 dark:divide-neutral-800">
          {filteredUsers.map(user => (
            <li
              key={user.id}
              onClick={() => onSelectUser(user)}
              className="p-3 cursor-pointer hover:bg-primary-50 dark:hover:bg-primary-900/20 rounded-lg transition"
            >
              <div className="flex justify-between items-center">
                <div>
                  <p className="font-semibold text-neutral-900 dark:text-white">{user.first_name} {user.last_name}</p>
                  <p className="text-xs text-neutral-500 dark:text-neutral-400">{user.email} | {user.role}</p>
                </div>
              </div>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
};

export default UsersList;
